-- FinDost AI schema (generated by backend/scripts/export_schema.py)

CREATE TABLE IF NOT EXISTS businesses (
	id VARCHAR(36) NOT NULL, 
	owner_id VARCHAR(64) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	city VARCHAR(80), 
	currency VARCHAR(3) NOT NULL, 
	opening_date DATE NOT NULL, 
	opening_cash_paisa BIGINT NOT NULL, 
	opening_bank_paisa BIGINT NOT NULL, 
	opening_wallet_paisa BIGINT NOT NULL, 
	cash_reserve_paisa BIGINT NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	demo_anchor DATE, 
	ai_consent BOOLEAN NOT NULL, 
	language VARCHAR(5) NOT NULL, 
	recovery_weights JSON, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_business_owner UNIQUE (owner_id), 
	CONSTRAINT ck_business_kind CHECK (kind IN ('sme', 'student', 'household', 'enterprise'))
);
CREATE INDEX IF NOT EXISTS ix_businesses_owner_id ON businesses (owner_id);
ALTER TABLE public."businesses" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS customers (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	notes VARCHAR(240), 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_customer_name UNIQUE (business_id, name), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_customers_business_id ON customers (business_id);
ALTER TABLE public."customers" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS financial_scenarios (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	description VARCHAR(400), 
	kind VARCHAR(12) NOT NULL, 
	adjustments JSON NOT NULL, 
	last_result JSON, 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_financial_scenarios_business_id ON financial_scenarios (business_id);
ALTER TABLE public."financial_scenarios" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS forecast_runs (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	run_date DATE NOT NULL, 
	input_hash VARCHAR(64) NOT NULL, 
	model_name VARCHAR(40) NOT NULL, 
	horizon_days INTEGER NOT NULL, 
	opening_balance_paisa BIGINT NOT NULL, 
	min_balance_paisa BIGINT NOT NULL, 
	shortage_date DATE, 
	summary JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_forecast_day UNIQUE (business_id, run_date), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_forecast_runs_business_id ON forecast_runs (business_id);
ALTER TABLE public."forecast_runs" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS import_batches (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	filename VARCHAR(200) NOT NULL, 
	adapter VARCHAR(40) NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	rows JSON NOT NULL, 
	summary JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_import_batches_business_id ON import_batches (business_id);
ALTER TABLE public."import_batches" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS products (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	sku VARCHAR(40) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	unit VARCHAR(16) NOT NULL, 
	unit_cost_paisa BIGINT NOT NULL, 
	sale_price_paisa BIGINT NOT NULL, 
	reorder_level INTEGER NOT NULL, 
	lead_time_days INTEGER NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_product_sku UNIQUE (business_id, sku), 
	CONSTRAINT ck_product_cost CHECK (unit_cost_paisa >= 0), 
	CONSTRAINT ck_product_price CHECK (sale_price_paisa >= 0), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_products_business_id ON products (business_id);
ALTER TABLE public."products" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS risk_alerts (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	rule VARCHAR(40) NOT NULL, 
	entity_key VARCHAR(80) NOT NULL, 
	level VARCHAR(10) NOT NULL, 
	score INTEGER NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	status VARCHAR(14) NOT NULL, 
	first_detected_on DATE NOT NULL, 
	last_detected_on DATE NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_alert_rule_entity UNIQUE (business_id, rule, entity_key), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_risk_alerts_business_id ON risk_alerts (business_id);
ALTER TABLE public."risk_alerts" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS suppliers (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	category VARCHAR(60), 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_supplier_name UNIQUE (business_id, name), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_suppliers_business_id ON suppliers (business_id);
ALTER TABLE public."suppliers" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS inventory_movements (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	product_id VARCHAR(36) NOT NULL, 
	occurred_on DATE NOT NULL, 
	movement_type VARCHAR(16) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_value_paisa BIGINT NOT NULL, 
	transaction_id VARCHAR(36), 
	note VARCHAR(240), 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_inventory_movements_business_id ON inventory_movements (business_id);
CREATE INDEX IF NOT EXISTS ix_inventory_movements_product_id ON inventory_movements (product_id);
ALTER TABLE public."inventory_movements" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS payables (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	supplier_id VARCHAR(36), 
	reference VARCHAR(40), 
	description VARCHAR(240), 
	category VARCHAR(60) NOT NULL, 
	issued_on DATE NOT NULL, 
	due_on DATE NOT NULL, 
	amount_paisa BIGINT NOT NULL, 
	is_essential BOOLEAN NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_payable_amount CHECK (amount_paisa > 0), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE, 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS ix_payables_business_id ON payables (business_id);
ALTER TABLE public."payables" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS receivables (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	customer_id VARCHAR(36) NOT NULL, 
	reference VARCHAR(40), 
	description VARCHAR(240), 
	issued_on DATE NOT NULL, 
	due_on DATE NOT NULL, 
	expected_on DATE, 
	amount_paisa BIGINT NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_receivable_amount CHECK (amount_paisa > 0), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_receivables_business_id ON receivables (business_id);
ALTER TABLE public."receivables" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS scenario_actions (
	id VARCHAR(36) NOT NULL, 
	scenario_id VARCHAR(36) NOT NULL, 
	action_type VARCHAR(40) NOT NULL, 
	label VARCHAR(200) NOT NULL, 
	params JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(scenario_id) REFERENCES financial_scenarios (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_scenario_actions_scenario_id ON scenario_actions (scenario_id);
ALTER TABLE public."scenario_actions" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS transactions (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	occurred_on DATE NOT NULL, 
	kind VARCHAR(24) NOT NULL, 
	amount_paisa BIGINT NOT NULL, 
	account VARCHAR(10), 
	to_account VARCHAR(10), 
	category VARCHAR(60) NOT NULL, 
	description VARCHAR(240) NOT NULL, 
	customer_id VARCHAR(36), 
	supplier_id VARCHAR(36), 
	receivable_id VARCHAR(36), 
	payable_id VARCHAR(36), 
	source VARCHAR(16) NOT NULL, 
	import_batch_id VARCHAR(36), 
	dedupe_key VARCHAR(64), 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_tx_amount_positive CHECK (amount_paisa > 0), 
	CONSTRAINT ck_tx_kind CHECK (kind IN ('income', 'expense', 'credit_sale', 'customer_payment', 'credit_purchase', 'supplier_payment', 'loan_received', 'loan_repayment', 'owner_withdrawal', 'transfer')), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE SET NULL, 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL, 
	FOREIGN KEY(receivable_id) REFERENCES receivables (id) ON DELETE CASCADE, 
	FOREIGN KEY(payable_id) REFERENCES payables (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_transactions_dedupe_key ON transactions (dedupe_key);
CREATE INDEX IF NOT EXISTS ix_transactions_business_id ON transactions (business_id);
CREATE INDEX IF NOT EXISTS ix_transactions_payable_id ON transactions (payable_id);
CREATE INDEX IF NOT EXISTS ix_transactions_occurred_on ON transactions (occurred_on);
CREATE INDEX IF NOT EXISTS ix_transactions_receivable_id ON transactions (receivable_id);
ALTER TABLE public."transactions" ENABLE ROW LEVEL SECURITY;
